// The query database (lib/db.kfx, C399) checked against itself from
// scratch: after each of many random edits, a random query's value from the
// database that has seen every edit is the value a fresh database, given
// only the inputs as they are now, makes. Coopt's verifier's rule (and
// kayak's `incremental.rs` for kfx's memos), for the database itself.
//
// The inputs `x 0` to `x 4`, each a number 0 to 5, set at a random
// durability; the queries: `m I`, `x I` mod 3, so that edits often leave a
// value as it was (early cutoff); `s`, which reads `m 1` and `m 2` if `m 0`
// is 0, else `m 3` (what it reads depends on what it read: dynamic
// dependence); `t`, `s` and `m 4` summed; `u`, `big:` and `x 0` if `t` is
// more than 3, else `small` (reading `x 0` only sometimes). The answer:
// how many steps, how many disagreed, and how many bodies the database ran
// against how many the fresh ones did.
pub fn digits(mut cs: List<char>, mut n: i64) -> i64 {
    loop {
        if null_p(cs) {
            return n;
        } else {
            (cs, n) = (cdr(cs), i64_plus(i64_star(n, 10i64), i64_minus(char_to_i64(car(cs)), 48i64)));
            continue;
        }
    }
}

#[inline]
pub fn num(s: Str) -> i64 {
    digits(string_chars(s), 0i64)
}

pub fn key_after(mut cs: List<char>) -> Str {
    loop {
        if null_p(cs) {
            return str_lit("");
        } else if char_eq_p(car(cs), ' ') {
            return list_to_string(cdr(cs));
        } else {
            cs = cdr(cs);
            continue;
        }
    }
}

pub fn run(d: Db, k: Str) -> Str {
    let h = string_ref_i64(k, 0i64);
    if char_eq_p(h, 'm') {
        i64_to_string(i64_remainder(num(db_get(d, &run, string_append(str_lit("x "), key_after(string_chars(k))))), 3i64))
    } else if char_eq_p(h, 's') {
        if string_eq_p(db_get(d, &run, str_lit("m 0")), str_lit("0")) {
            i64_to_string(i64_plus(num(db_get(d, &run, str_lit("m 1"))), num(db_get(d, &run, str_lit("m 2")))))
        } else {
            db_get(d, &run, str_lit("m 3"))
        }
    } else if char_eq_p(h, 't') {
        i64_to_string(i64_plus(num(db_get(d, &run, str_lit("s"))), num(db_get(d, &run, str_lit("m 4")))))
    } else if char_eq_p(h, 'u') {
        if i64_gt(num(db_get(d, &run, str_lit("t"))), 3i64) {
            string_append(str_lit("big:"), db_get(d, &run, str_lit("x 0")))
        } else {
            str_lit("small")
        }
    } else {
        error(string_append(str_lit("no query "), k));
        str_lit("")
    }
}

// A linear congruential generator's next state, and a number below `n` of it.
#[inline]
pub fn next_seed(s: i64) -> i64 {
    i64_plus(i64_star(s, 6364136223846793005i64), 1442695040888963407i64)
}

#[inline]
pub fn below(s: i64, n: i64) -> i64 {
    i64_remainder(i64_and(i64_quotient(s, 65536i64), 2147483647i64), n)
}

pub fn nth(mut xs: List<i64>, mut i: i64) -> i64 {
    loop {
        if i64_eq(i, 0i64) {
            return car(xs);
        } else {
            (xs, i) = (cdr(xs), i64_minus(i, 1i64));
            continue;
        }
    }
}

pub fn put_at(xs: List<i64>, i: i64, x: i64) -> List<i64> {
    if i64_eq(i, 0i64) {
        kayak_rt::heap_cons(x, cdr(xs))
    } else {
        kayak_rt::heap_cons(car(xs), put_at(cdr(xs), i64_minus(i, 1i64), x))
    }
}

