// A fresh database with the inputs as they are, and the runs it took.
pub fn set_all_x(mut d: Db, mut vals: List<i64>, mut durs: List<i64>, mut i: i64) -> () {
    loop {
        if null_p(vals) {
            return ();
        } else {
            db_set_x(d, string_append(str_lit("x "), i64_to_string(i)), i64_to_string(car(vals)), car(durs));
            (vals, durs, i) = (cdr(vals), cdr(durs), i64_plus(i, 1i64));
            continue;
        }
    }
}

pub enum Tally {
    Tally(i64, i64, i64),
}

pub fn tally(f0: i64, f1: i64, f2: i64) -> &'static Tally {
    kayak_rt::heap_alloc(Tally::Tally(f0, f1, f2))
}

pub fn steps(d: Db, n: i64, seed: i64, vals: List<i64>, durs: List<i64>, acc: &'static Tally) -> &'static Tally {
    if i64_eq(n, 0i64) {
        acc
    } else {
        let s1 = next_seed(seed);
        let s2 = next_seed(s1);
        let s3 = next_seed(s2);
        let s4 = next_seed(s3);
        let i = below(s1, 5i64);
        let x = below(s2, 6i64);
        let du = below(s3, 4i64);
        let k = nth_key(query_keys(), below(s4, 8i64));
        let vals = put_at(vals, i, x);
        let durs = put_at(durs, i, du);
        db_set_x(d, string_append(str_lit("x "), i64_to_string(i)), i64_to_string(x), du);
        let before = db_runs(d);
        let got = db_get(d, &run, k);
        let ours = i64_minus(db_runs(d), before);
        let fresh = db_make();
        set_all_x(fresh, vals, durs, 0i64);
        let want = db_get(fresh, &run, k);
        let tagcase_ = acc;
        match *tagcase_ {
            Tally::Tally(wrong, mine, theirs) => {
                steps(d, i64_minus(n, 1i64), s4, vals, durs, tally(if string_eq_p(got, want) {
                    wrong
                } else {
                    i64_plus(wrong, 1i64)
                }, i64_plus(mine, ours), i64_plus(theirs, db_runs(fresh))))
            }
        }
    }
}

// The model's counterexample (models/db.qnt, C400), as it found it: `s`
